<script setup lang="ts">
import { useFormDrafts } from '@/composables/useFormDrafts'
import {computed,onMounted,reactive,ref} from 'vue'
import MainLayout from '@/components/MainLayout.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
type Row=Record<string,any>
const auth=useAuthStore(),data=reactive<Record<string,Row[]>>({}),error=ref(''),message=ref(''),busy=ref(false),modal=ref(false),mode=ref('week'),selectedDate=ref(local(new Date()).slice(0,10)),form=reactive<Row>({})
function local(d:Date){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const canEdit=computed(()=>[1,2,9].includes(auth.effectiveRoleId))
const days=computed(()=>{const date=new Date(selectedDate.value+'T00:00:00');if(mode.value==='month')date.setDate(1);else date.setDate(date.getDate()-(date.getDay()+6)%7);const count=mode.value==='week'?7:new Date(date.getFullYear(),date.getMonth()+1,0).getDate();return Array.from({length:count},(_,i)=>{const d=new Date(date);d.setDate(d.getDate()+i);const end=new Date(d);end.setDate(end.getDate()+1);return {date:local(d).slice(0,10),label:d.toLocaleDateString('zh-CN',{month:'numeric',day:'numeric',weekday:'short'}),rows:(data.schedules||[]).filter(r=>new Date(r.start_at)<end&&new Date(r.end_at)>d)}})})
function label(key:string,id:any){const r=data[key]?.find(r=>Number(r.id)===Number(id));return r?.name||r?.real_name||'未关联'}
function members(team:any){return (data.members||[]).filter(m=>Number(m.team_id)===Number(team)).map(m=>label('users',m.user_id)).join('、')}
async function load(){try{await Promise.all(['schedules','teams','members','shifts','stations','equipment','users'].map(async k=>data[k]=await request.get(`/foundation/${k}`)));data.tasks=await request.get('/fulfillment/work-orders')}catch(e:any){error.value=e.message}}
function edit(row?:Row){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row||{team_id:'',shift_id:'',station_id:'',equipment_id:'',start_at:selectedDate.value+'T08:00',end_at:selectedDate.value+'T16:00'});for(const k of ['start_at','end_at'])form[k]=String(form[k]).replace(' ','T').slice(0,16);modal.value=true;error.value=''}
function shift(){const s=data.shifts?.find(s=>Number(s.id)===Number(form.shift_id));if(!s)return;const day=form.start_at.slice(0,10);form.start_at=day+'T'+s.start_time;const end=new Date(day+'T'+s.end_time);if(s.end_time<=s.start_time)end.setDate(end.getDate()+1);form.end_at=local(end)}
async function save(){busy.value=true;try{if(form.id)await request.put(`/foundation/schedules/${form.id}`,form);else await request.post('/foundation/schedules',form);completeDrafts();modal.value=false;message.value='排班已保存，已校验人员、工作站和设备冲突';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function cancel(r:Row){if(!confirm('确认停班？已关联制造任务的排班会保留并阻止删除。'))return;try{await request.delete(`/foundation/schedules/${r.id}`);await load()}catch(e:any){error.value=e.message}}
async function copy(){busy.value=true;try{await request.post('/foundation/schedule-planning/copy-week',{week_start:days.value[0].date});message.value='已复制本周排班到下一周；人员或资源冲突会整批回滚';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function scheduleTime(r:Row){const start=String(r.start_at).replace('T',' '),end=String(r.end_at).replace('T',' ');return `${start.slice(11,16)} — ${end.slice(11,16)}${start.slice(0,10)!==end.slice(0,10)?' · 跨日':''}`}
const periodSchedules=computed(()=>{const ids=new Map();days.value.forEach(day=>day.rows.forEach(r=>ids.set(r.id,r)));return [...ids.values()] as Row[]})
onMounted(load)

const completeDrafts=useFormDrafts({modal:{open:modal,fields:{form}, record:()=>(form as Record<string,any>).id}})
</script>
<template><MainLayout><div class="schedule-page"><h1 class="text-2xl font-bold">班组排班计划</h1><p class="text-gray-500">按班组和班次排班，跨日班次自动延续至次日。负责人由班组维护，制造工单可关联排班。</p><div class="schedule-overview"><div><span>本期排班</span><strong>{{periodSchedules.length}}<small>个班次</small></strong></div><div><span>参与班组</span><strong>{{new Set(periodSchedules.map(r=>r.team_id)).size}}<small>个班组</small></strong></div><div><span>覆盖天数</span><strong>{{days.filter(d=>d.rows.length).length}}<small>/ {{days.length}} 天</small></strong></div></div><div class="schedule-toolbar"><input v-model="selectedDate" type="date" class="input w-auto"/><select v-model="mode" class="input w-auto"><option value="week">周视图</option><option value="month">月视图</option></select><button @click="load" class="btn-secondary">刷新</button><template v-if="canEdit"><button @click="edit()" class="btn-primary">新增排班</button><button v-if="mode==='week'" :disabled="busy" @click="copy" class="btn-secondary">复制本周到下周</button><router-link class="btn-secondary" to="/foundation/rotations">配置周期轮班</router-link></template><router-link class="btn-secondary" to="/foundation/teams">班组与成员配置</router-link></div><p v-if="error" role="alert" class="text-red-600">{{error}}</p><p v-if="message" class="text-green-700">{{message}}</p><div class="schedule-calendar" :class="{monthly:mode==='month'}"><section v-for="day in days" :key="day.date" class="schedule-day" :class="{selected:day.date===selectedDate}"><header><h2>{{day.label}}</h2><span>{{day.rows.length}} 班</span></header><article v-for="r in day.rows" :key="r.id" class="schedule-event"><strong>{{label('teams',r.team_id)}}</strong><p class="event-shift">{{label('shifts',r.shift_id)}}</p><p class="event-time" :title="`${r.start_at} 至 ${r.end_at}`">{{scheduleTime(r)}}</p><p>工作站：{{label('stations',r.station_id)}}</p><p>负责人：{{label('users',data.teams?.find(t=>Number(t.id)===Number(r.team_id))?.leader_id)}}</p><p>成员：{{members(r.team_id)}}</p><div v-if="canEdit" class="flex gap-3"><button @click="edit(r)" class="text-blue-700">调班</button><button @click="cancel(r)" class="text-red-700">停班</button></div></article><p v-if="!day.rows.length" class="schedule-empty">—<span>暂无排班</span></p></section></div><router-link to="/manufacturing" class="link-btn">前往制造工单关联排班 →</router-link></div><div v-if="modal" class="modal-mask" data-business-form><form @submit.prevent="save" class="modal-card space-y-4 max-w-xl"><p class="text-xs text-gray-500 mb-3" role="note">退出填写会保留草稿；保存成功后自动关闭。</p><h2 class="font-bold text-xl">{{form.id?'调整排班':'新增排班'}}</h2><p v-if="error" class="text-red-600">{{error}}</p><label v-for="f in [{key:'team_id',name:'班组',source:'teams'},{key:'shift_id',name:'班次',source:'shifts'},{key:'station_id',name:'工作站',source:'stations'},{key:'equipment_id',name:'设备（可选）',source:'equipment'}]" :key="f.key" class="block">{{f.name}}<select v-model="form[f.key]" :required="f.key!=='equipment_id'" @change="f.key==='shift_id'&&shift()" class="input"><option value="">请选择</option><option v-for="r in data[f.source]" :key="r.id" :value="r.id">{{r.name||r.equipment_name}}</option></select></label><label class="block">开始时间<input v-model="form.start_at" type="datetime-local" required class="input" data-date-role="start" data-date-pair="_at"></label><label class="block">结束时间<input v-model="form.end_at" type="datetime-local" required class="input" data-date-role="end" data-date-pair="_at"></label><div class="flex justify-end gap-3"><button type="button" @click="modal=false">取消</button><button :disabled="busy" class="btn-primary">保存并检查冲突</button></div></form></div></MainLayout></template>

<style scoped>
.schedule-page{display:flex;flex-direction:column;gap:18px}.schedule-page>h1{font-size:18px!important;color:#7b6040;margin:0}.schedule-page>p{font-size:12px;line-height:1.7;margin:0}.schedule-overview{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.schedule-overview>div{border:1px solid #e7dfd1;border-radius:10px;padding:14px 18px;background:#f3eee4}.schedule-overview span{font-size:11px;color:#a08d70}.schedule-overview strong{display:block;font-size:25px;color:#80623e;font-weight:600;margin-top:5px}.schedule-overview small{font-size:11px;font-weight:400;color:#a08d70;margin-left:8px}.schedule-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;background:#fffdf9;padding:14px;border:1px solid #e7dfd1;border-radius:10px}.schedule-toolbar :is(button,a,input,select){font-size:12px}.schedule-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px;align-items:start}.schedule-day{min-width:0;border:1px solid #e8e1d5;border-radius:10px;background:#fffdf9;overflow:hidden;min-height:220px}.schedule-day.selected{border-color:#c6aa7f;box-shadow:0 0 0 1px #c6aa7f22}.schedule-day header{padding:12px 10px;border-bottom:1px solid #eee7db;background:#f7f3eb;display:flex;justify-content:space-between;gap:4px;align-items:center}.schedule-day h2{font-size:12px;font-weight:600;color:#806748}.schedule-day header>span{font-size:10px;color:#b19e82;white-space:nowrap}.schedule-event{margin:9px;padding:11px 9px;border:1px solid #e7dbc6;border-left:3px solid #b59567;border-radius:7px;background:#f6f0e5;color:#8e7a5d;font-size:11px;line-height:1.7;overflow-wrap:anywhere}.schedule-event strong{display:block;color:#79603e;font-size:12px;line-height:1.6}.schedule-event p{margin-top:6px}.schedule-event .event-shift{font-size:10px;color:#a08b6b}.schedule-event .event-time{color:#8a6a3f;font-weight:500;font-variant-numeric:tabular-nums;padding-bottom:7px;border-bottom:1px solid #e7ddcc}.schedule-event>div{margin-top:10px;padding-top:6px;border-top:1px solid #e7ddcc;font-size:11px}.schedule-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:160px;gap:7px;font-size:18px;color:#d1c5b1}.schedule-empty span{font-size:11px;color:#b8ac99}.monthly .schedule-day{min-height:160px}.monthly .schedule-empty{min-height:105px}@media(max-width:1100px){.schedule-calendar{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:700px){.schedule-calendar{grid-template-columns:repeat(2,minmax(0,1fr))}.schedule-overview>div{padding:12px}.schedule-toolbar .input{flex:1;min-width:120px}.schedule-day{min-height:180px}.schedule-empty{min-height:120px}}
</style>
